from collections import deque

def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols or
        grid[start_row][start_col] == '#' or
        grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    visited_forward = set()
    visited_backward = set()
    forward_queue = deque([(start_row, start_col, [start])])
    backward_queue = deque([(goal_row, goal_col, [goal])])

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    while forward_queue and backward_queue:
        # Expand forward direction
        if forward_queue:
            fr, fc, path = forward_queue.popleft()
            if (fr, fc) in visited_forward:
                continue
            visited_forward.add((fr, fc))
            for dr, dc in directions:
                nr, nc = fr + dr, fc + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited_forward:
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_backward:
                        return new_path
                    forward_queue.append((nr, nc, new_path))

        # Expand backward direction
        if backward_queue:
            br, bc, path = backward_queue.popleft()
            if (br, bc) in visited_backward:
                continue
            visited_backward.add((br, bc))
            for dr, dc in directions:
                nr, nc = br + dr, bc + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited_backward:
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_forward:
                        return new_path
                    backward_queue.append((nr, nc, new_path))

    return []

