        while queue:
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c)
                    queue.append((nr, nc))
                    if (nr, nc) == goal:
                        return True
        return False

    start_queue = deque([start])
    start_visited = {start}
    start_parent = {}

    goal_queue = deque([goal])
    goal_visited = {goal}
    goal_parent = {}

    while start_queue and goal_queue:
        if bfs(start_queue, start_visited, start_parent):
            path = []
            current = goal
            while current != start:
                path.append(current)
                current = start_parent[current]
            path.append(start)
            return path[::-1]
