from collections import deque

def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0])) or \
       not (0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])) or \
       grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []

    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])

    def is_free(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def get_neighbors(r, c):
        return [(r+dr, c+dc) for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)] if is_free(r+dr, c+dc)]

    forward = {start: [start]}
    backward = {goal: [goal]}
    visited_forward = set([start])
    visited_backward = set([goal])

    while True:
        if forward and backward:
            forward_keys = list(forward.keys())
            for node in forward_keys:
                for neighbor in get_neighbors(node[0], node[1]):
                    if neighbor in backward:
                        path = forward[node] + [neighbor]
                        return path
                    if neighbor not in visited_forward:
                        visited_forward.add(neighbor)
                        forward[neighbor] = forward[node] + [neighbor]
            backward_keys = list(backward.keys())
            for node in backward_keys:
                for neighbor in get_neighbors(node[0], node[1]):
                    if neighbor in forward:
                        path = backward[node] + [neighbor]
                        return path
                    if neighbor not in visited_backward:
                        visited_backward.add(neighbor)
                        backward[neighbor] = backward[node] + [neighbor]
        else:
            return []

