        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    pq = [(heuristic(start, goal), 0, start_row, start_col, [start])]
    visited = set()

    while pq:
        _, _, r, c, path = heapq.heappop(pq)
        if (r, c) == goal:
