def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    # Check if start or goal is invalid
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue for IDA* (f = g + heuristic)
    # Each entry is (f, g, path, row, col)
    def manhattan_dist(r1, c1, r2, c2):
        return abs(r1 - r2) + abs(c1 - c2)

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # IDA* search
    def ida_star():
        def dfs(r, c, g, f, path):
            if f > bound:
                return f
            if (r, c) == goal:
                return None
            min_f = float('inf')
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in path:
                    next_g = g + 1
                    next_f = next_g + manhattan_dist(nr, nc, goal[0], goal[1])
                    result = dfs(nr, nc, next_g, next_f, path + [(nr, nc)])
                    if result is None:
                        return None
                    if result < min_f:
                        min_f = result
            return min_f

        bound = manhattan_dist(start[0], start[1], goal[0], goal[1])
        while True:
            result = dfs(start[0], start[1], 0, bound, [start])
            if result is None:
                return []
            if result == 0:
                return path
