def solve(grid, start, goal):
    if not (0 <= start[0] < len(grid) and 0 <= start[1] < len(grid[0]) or
            0 <= goal[0] < len(grid) and 0 <= goal[1] < len(grid[0])):
        return []
    if grid[start[0]][start[1]] == '#' or grid[goal[0]][goal[1]] == '#':
        return []
    if start == goal:
        return [start]

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = {}

    stack = [(start[0], start[1])]
    visited[start[0]][start[1]] = True

    while stack:
        r, c = stack[-1]
        neighbors = []
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and not visited[nr][nc] and grid[nr][nc] == '.':
                neighbors.append((nr, nc))
        if neighbors:
            next_r, next_c = neighbors[0]
            visited[next_r][next_c] = True
            path[(next_r, next_c)] = (r, c)
            stack.append((next_r, next_c))
        else:
            if stack.pop() == start:
                return []
            if stack[-1] == goal:
                break

    if stack[-1] != goal:
        return []

    path_list = []
    current = goal
    while current != start:
        path_list.append(current)
        current = path[current]
    path_list.append(start)
    path_list.reverse()
    return path_list
