def solve(grid, start, goal):
    if not grid or not start or not goal:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if (start_row < 0 or start_row >= rows or start_col < 0 or
        start_col >= cols or grid[start_row][start_col] == '#' or
        goal_row < 0 or goal_row >= rows or goal_col < 0 or
        goal_col >= cols or grid[goal_row][goal_col] == '#'):
        return []

    if start == goal:
        return [start]

    visited = set()
    path = []

    def backtrack(row, col, path):
        if (row, col) == goal:
            return True
        visited.add((row, col))
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_row, new_col = row + dr, col + dc
            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == '.' and (new_row, new_col) not in visited:
                path.append((new_row, new_col))
                if backtrack(new_row, new_col, path):
                    return True
                path.pop()
        return False

    if backtrack(start_row, start_col, path):
        return [start] + path
    else:
        return []

